1	/**
2	 * board.js — Canvas-based Go board renderer.
3	 *
4	 * Draws a Go board with:
5	 * - Wood-texture background gradient
6	 * - Anti-aliased stones with 3D gradient effect
7	 * - Star points (hoshi) at standard positions
8	 * - Coordinate labels (A-T, 1-19)
9	 * - Last-move indicator (small dot)
10	 * - Hover preview (semi-transparent stone)
11	 * - Territory estimation overlay (semi-transparent colors)
12	 * - Click-to-play with snap-to-intersection
13	 */
14	
15	class GoBoardRenderer {
16	    /**
17	     * @param {HTMLCanvasElement} canvas - The canvas element to draw on.
18	     * @param {number} boardSize - Board dimension (7, 9, 13, 15, or 19).
19	     * @param {function} onClickCallback - Called with (row, col) when user clicks.
20	     */
21	    constructor(canvas, boardSize = 9, onClickCallback = null) {
22	        this.canvas = canvas;
23	        this.ctx = canvas.getContext('2d');
24	        this.boardSize = boardSize;
25	        this.onClick = onClickCallback;
26	
27	        // Layout constants
28	        this.padding = 35;          // Space for labels
29	        this.cellSize = 0;          // Computed in resize
30	        this.stoneRadius = 0;
31	
32	        // State
33	        this.grid = [];             // 2D array: 0=empty, 1=black, 2=white
34	        this.lastMove = null;       // {row, col} of last move
35	        this.hoverPos = null;       // {row, col} under cursor
36	        this.currentPlayer = 1;     // For hover preview color
37	        this.ownershipMap = null;   // Territory estimation overlay
38	        this.showEstimate = false;
39	        this.suggestedMove = null;  // {row, col} for move suggestion
40	
41	        this._initGrid();
42	        this.resize();
43	        this._bindEvents();
44	        this.draw();
45	    }
46	
47	    _initGrid() {
48	        this.grid = Array.from({ length: this.boardSize }, () =>
49	            Array(this.boardSize).fill(0)
50	        );
51	    }
52	
53	    resize(forceSize = null) {
54	        let totalSize;
55	        if (forceSize) {
56	            totalSize = forceSize;
57	        } else if (this.canvas.parentElement) {
58	            totalSize = this.canvas.parentElement.clientWidth;
59	        } else {
60	            totalSize = Math.min(600, window.innerWidth - 20);
61	        }
62	        
63	        // Handle high-DPI displays
64	        const dpr = window.devicePixelRatio || 1;
65	        this.canvas.width = totalSize * dpr;
66	        this.canvas.height = totalSize * dpr;
67	        
68	        // Scale context to match CSS pixels
69	        this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
70	
71	        this.cellSize = (totalSize - 2 * this.padding) / (this.boardSize - 1);
72	        this.stoneRadius = this.cellSize * 0.43;
73	        
74	        // Store logical size for draw calculations
75	        this.logicalWidth = totalSize;
76	        this.logicalHeight = totalSize;
77	        
78	        // Redraw if grid is initialized
79	        if (this.grid.length > 0) {
80	            this.draw();
81	        }
82	    }
83	
84	    _bindEvents() {
85	        this.canvas.addEventListener('mousemove', (e) => {
86	            const pos = this._canvasToBoard(e.offsetX, e.offsetY);
87	            if (pos && (this.hoverPos?.row !== pos.row || this.hoverPos?.col !== pos.col)) {
88	                this.hoverPos = pos;
89	                this.draw();
90	            }
91	        });
92	
93	        this.canvas.addEventListener('mouseleave', () => {
94	            this.hoverPos = null;
95	            this.draw();
96	        });
97	
98	        this.canvas.addEventListener('click', (e) => {
99	            const pos = this._canvasToBoard(e.offsetX, e.offsetY);
100	            if (pos && this.onClick) {
101	                this.onClick(pos.row, pos.col);
102	            }
103	        });
104	    }
105	
106	    /** Convert canvas pixel coords to board (row, col). */
107	    _canvasToBoard(x, y) {
108	        const col = Math.round((x - this.padding) / this.cellSize);
109	        const row = Math.round((y - this.padding) / this.cellSize);
110	        if (row >= 0 && row < this.boardSize && col >= 0 && col < this.boardSize) {
111	            return { row, col };
112	        }
113	        return null;
114	    }
115	
116	    /** Convert board (row, col) to canvas pixel coords. */
117	    _boardToCanvas(row, col) {
118	        return {
119	            x: this.padding + col * this.cellSize,
120	            y: this.padding + row * this.cellSize,
121	        };
122	    }
123	
124	    /** Update the board state from a game state dict. */
125	    updateState(state) {
126	        this.boardSize = state.board_size;
127	        this.grid = state.grid;
128	        this.currentPlayer = state.current_player;
129	
130	        // Find last move
131	        if (state.move_history && state.move_history.length > 0) {
132	            const last = state.move_history[state.move_history.length - 1];
133	            if (last.move[0] >= 0 && last.move[1] >= 0) {
134	                this.lastMove = { row: last.move[0], col: last.move[1] };
135	            } else {
136	                this.lastMove = null;
137	            }
138	        } else {
139	            this.lastMove = null;
140	        }
141	
142	        this.resize();
143	    }
144	
145	    /** Set territory estimation overlay data. */
146	    setOwnershipMap(map) {
147	        this.ownershipMap = map;
148	        this.draw();
149	    }
150	
151	    /** Main draw function. */
152	    draw() {
153	        const ctx = this.ctx;
154	        const w = this.logicalWidth || this.canvas.width;
155	        const h = this.logicalHeight || this.canvas.height;
156	
157	        // Clear
158	        ctx.clearRect(0, 0, w, h);
159	
160	        // Board background (wood gradient)
161	        const grad = ctx.createLinearGradient(0, 0, w, h);
162	        grad.addColorStop(0, '#dcb35c');
163	        grad.addColorStop(0.5, '#d4a84a');
164	        grad.addColorStop(1, '#c49a3c');
165	        ctx.fillStyle = grad;
166	        ctx.beginPath();
167	        ctx.roundRect(0, 0, w, h, 12);
168	        ctx.fill();
169	
170	        // Wood grain effect (subtle lines)
171	        ctx.strokeStyle = 'rgba(139, 98, 68, 0.08)';
172	        ctx.lineWidth = 1;
173	        for (let i = 0; i < h; i += 7) {
174	            ctx.beginPath();
175	            ctx.moveTo(0, i + Math.sin(i * 0.05) * 3);
176	            ctx.lineTo(w, i + Math.sin(i * 0.05 + 2) * 3);
177	            ctx.stroke();
178	        }
179	
180	        // Grid lines
181	        ctx.strokeStyle = '#3a2a0a';
182	        ctx.lineWidth = 1;
183	        for (let i = 0; i < this.boardSize; i++) {
184	            const p = this.padding + i * this.cellSize;
185	            // Vertical
186	            ctx.beginPath();
187	            ctx.moveTo(p, this.padding);
188	            ctx.lineTo(p, this.padding + (this.boardSize - 1) * this.cellSize);
189	            ctx.stroke();
190	            // Horizontal
191	            ctx.beginPath();
192	            ctx.moveTo(this.padding, p);
193	            ctx.lineTo(this.padding + (this.boardSize - 1) * this.cellSize, p);
194	            ctx.stroke();
195	        }
196	
197	        // Star points (hoshi)
198	        this._drawStarPoints(ctx);
199	
200	        // Coordinate labels
201	        this._drawLabels(ctx);
202	
203	        // Territory estimation overlay
204	        if (this.showEstimate && this.ownershipMap) {
205	            this._drawOwnership(ctx);
206	        }
207	
208	        // Stones
209	        for (let r = 0; r < this.boardSize; r++) {
210	            for (let c = 0; c < this.boardSize; c++) {
211	                if (this.grid[r] && this.grid[r][c] !== 0) {
212	                    this._drawStone(ctx, r, c, this.grid[r][c]);
213	                }
214	            }
215	        }
216	
217	        // Last move indicator
218	        if (this.lastMove) {
219	            this._drawLastMoveMarker(ctx, this.lastMove.row, this.lastMove.col);
220	        }
221	
222	        // Suggested move
223	        if (this.suggestedMove) {
224	            this._drawSuggestion(ctx, this.suggestedMove.row, this.suggestedMove.col);
225	        }
226	
227	        // Hover preview
228	        if (this.hoverPos && this.grid[this.hoverPos.row]?.[this.hoverPos.col] === 0) {
229	            this._drawHoverPreview(ctx, this.hoverPos.row, this.hoverPos.col);
230	        }
231	    }
232	
233	    _drawStone(ctx, row, col, color) {
234	        const { x, y } = this._boardToCanvas(row, col);
235	        const r = this.stoneRadius;
236	
237	        // Shadow
238	        ctx.beginPath();
239	        ctx.arc(x + 1.5, y + 1.5, r, 0, Math.PI * 2);
240	        ctx.fillStyle = 'rgba(0,0,0,0.3)';
241	        ctx.fill();
242	
243	        // Stone body
244	        ctx.beginPath();
245	        ctx.arc(x, y, r, 0, Math.PI * 2);
246	        if (color === 1) {
247	            // Black stone gradient
248	            const g = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, r * 0.1, x, y, r);
249	            g.addColorStop(0, '#555');
250	            g.addColorStop(0.5, '#222');
251	            g.addColorStop(1, '#111');
252	            ctx.fillStyle = g;
253	        } else {
254	            // White stone gradient
255	            const g = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, r * 0.1, x, y, r);
256	            g.addColorStop(0, '#fff');
257	            g.addColorStop(0.5, '#eee');
258	            g.addColorStop(1, '#ccc');
259	            ctx.fillStyle = g;
260	        }
261	        ctx.fill();
262	
263	        // Shine highlight
264	        ctx.beginPath();
265	        ctx.arc(x - r * 0.25, y - r * 0.25, r * 0.2, 0, Math.PI * 2);
266	        ctx.fillStyle = color === 1 ? 'rgba(255,255,255,0.15)' : 'rgba(255,255,255,0.5)';
267	        ctx.fill();
268	    }
269	
270	    _drawStarPoints(ctx) {
271	        const points = this._getStarPoints();
272	        ctx.fillStyle = '#3a2a0a';
273	        for (const [r, c] of points) {
274	            const { x, y } = this._boardToCanvas(r, c);
275	            ctx.beginPath();
276	            ctx.arc(x, y, 3, 0, Math.PI * 2);
277	            ctx.fill();
278	        }
279	    }
280	
281	    _getStarPoints() {
282	        const s = this.boardSize;
283	        if (s === 9) return [[2,2],[2,6],[4,4],[6,2],[6,6]];
284	        if (s === 13) return [[3,3],[3,9],[6,6],[9,3],[9,9]];
285	        if (s === 19) return [[3,3],[3,9],[3,15],[9,3],[9,9],[9,15],[15,3],[15,9],[15,15]];
286	        if (s === 7) return [[3,3]];
287	        if (s === 15) return [[3,3],[3,11],[7,7],[11,3],[11,11]];
288	        return [];
289	    }
290	
291	    _drawLabels(ctx) {
292	        ctx.fillStyle = '#5a4a2a';
293	        ctx.font = `${Math.max(10, this.cellSize * 0.35)}px Inter, sans-serif`;
294	        ctx.textAlign = 'center';
295	        ctx.textBaseline = 'middle';
296	
297	        const letters = 'ABCDEFGHJKLMNOPQRST'; // Skip 'I' in Go
298	        for (let i = 0; i < this.boardSize; i++) {
299	            const p = this.padding + i * this.cellSize;
300	            // Top/bottom column labels
301	            ctx.fillText(letters[i], p, 12);
302	            ctx.fillText(letters[i], p, this.logicalHeight - 10);
303	            // Left/right row labels
304	            const rowNum = this.boardSize - i;
305	            ctx.fillText(rowNum, 12, p);
306	            ctx.fillText(rowNum, this.logicalWidth - 12, p);
307	        }
308	    }
309	
310	    _drawLastMoveMarker(ctx, row, col) {
311	        const { x, y } = this._boardToCanvas(row, col);
312	        const color = this.grid[row][col];
313	        ctx.beginPath();
314	        ctx.arc(x, y, this.stoneRadius * 0.3, 0, Math.PI * 2);
315	        ctx.fillStyle = color === 1 ? '#fff' : '#333';
316	        ctx.fill();
317	    }
318	
319	    _drawHoverPreview(ctx, row, col) {
320	        const { x, y } = this._boardToCanvas(row, col);
321	        ctx.beginPath();
322	        ctx.arc(x, y, this.stoneRadius, 0, Math.PI * 2);
323	        ctx.fillStyle = this.currentPlayer === 1 ? 'rgba(0,0,0,0.3)' : 'rgba(255,255,255,0.3)';
324	        ctx.fill();
325	    }
326	
327	    _drawSuggestion(ctx, row, col) {
328	        const { x, y } = this._boardToCanvas(row, col);
329	        ctx.beginPath();
330	        ctx.arc(x, y, this.stoneRadius * 0.6, 0, Math.PI * 2);
331	        ctx.strokeStyle = '#4caf50';
332	        ctx.lineWidth = 2;
333	        ctx.stroke();
334	        ctx.fillStyle = 'rgba(76, 175, 80, 0.2)';
335	        ctx.fill();
336	    }
337	
338	    _drawOwnership(ctx) {
339	        if (!this.ownershipMap) return;
340	        for (let r = 0; r < this.boardSize; r++) {
341	            for (let c = 0; c < this.boardSize; c++) {
342	                const val = this.ownershipMap[r]?.[c] || 0;
343	                if (Math.abs(val) < 0.1) continue;
344	
345	                const { x, y } = this._boardToCanvas(r, c);
346	                const size = this.cellSize * 0.4;
347	
348	                if (val < 0) {
349	                    // Black territory
350	                    ctx.fillStyle = `rgba(30, 30, 30, ${Math.abs(val) * 0.5})`;
351	                } else {
352	                    // White territory
353	                    ctx.fillStyle = `rgba(255, 255, 255, ${Math.abs(val) * 0.4})`;
354	                }
355	                ctx.fillRect(x - size, y - size, size * 2, size * 2);
356	            }
357	        }
358	    }
359	}
