/* ============================================
   Go AI — Dark Theme with Wood Accents
   ============================================ */

:root {
    --bg-primary: #0f1117;
    --bg-secondary: #1a1d27;
    --bg-card: rgba(26, 29, 39, 0.85);
    --bg-glass: rgba(255, 255, 255, 0.04);
    --border-glass: rgba(255, 255, 255, 0.08);
    --text-primary: #e8e6e3;
    --text-secondary: #9a9a9a;
    --text-muted: #5a5a5a;
    --accent: #c8956c;        /* Warm wood tone */
    --accent-light: #dbb08a;
    --accent-dark: #8b6244;
    --success: #4caf50;
    --danger: #ef5350;
    --warning: #ffa726;
    --board-color: #dcb35c;   /* Go board wood */
    --board-dark: #c49a3c;
    --radius: 12px;
    --radius-sm: 8px;
    --shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    min-height: 100vh;
    line-height: 1.6;
}

/* ---- Navbar ---- */
.navbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1.5rem;
    padding: 0.9rem 2.5rem;
    background: linear-gradient(180deg, var(--bg-secondary), rgba(26, 29, 39, 0.92));

