for lo,hi,tag in [(20,26,'BEFORE collapse (20-26)'),(41,48,'AFTER collapse (41-48)')]:
    g=load(lo,hi)
    pb=pw=0; sb=sw=0; firstpass=[]
    for d in g:
        for m in d['moves']:
            ispass = m['move'][0] < 0
            if m['color']==1:
                sb+=1; pb+= ispass
            else:
                sw+=1; pw+= ispass
