(async () => {
  await new Promise(r => setTimeout(r, 1500));
  const api = await (await fetch('/training/api/metrics')).json();
  const out = { apiRows: api.length };
  const charts = { elo:'elo-chart', policy:'policy-loss-chart', value:'value-loss-chart' };
  for (const [name,id] of Object.entries(charts)) {
    const c = Chart.getChart(document.getElementById(id));
    if (!c) { out[name] = 'NO CHART'; continue; }
    const labels = c.data.labels;
    out[name] = { points: labels.length, first: labels[0], last: labels[labels.length-1],
                  distinct: new Set(labels).size };
  }
  return JSON.stringify(out, null, 1);
})();

