(async () => {
  await new Promise(r => setTimeout(r, 1800));
  const elo = () => Chart.getChart(document.getElementById('elo-chart'));
  const out = {};
  out.initial = elo().data.labels.length;

  // 1) replay the SAME iteration many times (socket redelivery)
  for (let i=0;i<5;i++) updateCharts({iteration: 12, elo: 640, policy_loss: 3, value_loss: .3});
  out.afterReplayingIter12x5 = elo().data.labels.length;

  // 2) replay the ENTIRE history again (the model-switch / restart case)
  const api = await (await fetch('/training/api/metrics')).json();
  api.forEach(m => updateCharts(m));
  out.afterReplayingWholeHistory = elo().data.labels.length;

  // 3) out-of-order arrival stays sorted
  updateCharts({iteration: 5, elo: 555});
  const labels = elo().data.labels.map(l => parseInt(l.replace('Iter ',''),10));
  out.sorted = labels.every((v,i,a) => i===0 || a[i-1] <= v);
  out.duplicates = labels.length - new Set(labels).size;

  // 4) full reload is idempotent
  await loadHistoricalMetrics();
  out.afterFullReload = elo().data.labels.length;
  out.apiRows = api.length;
  return JSON.stringify(out, null, 1);
})();

