  const out = {};
  out.consoleOk = true;
  out.chartExists = !!gateChart;
  out.realPoints = gateChart ? gateChart.data.labels.length : null;
  out.statsReal = ['gate-elo','gate-promotions','gate-avg','gate-streak','gate-champ-version']
      .reduce((a,id)=>(a[id]=document.getElementById(id).textContent,a),{});

  // Feed a richer synthetic lineage to exercise promotions + ladder
  const wrs=[0.5,0.6,0.5,0.5,0.7,0.55,0.4,0.4,0.4,0.8];
  let elo=0, ver=1, promos=0, streak=0, last=null;
  const pts=wrs.map((wr,i)=>{
    const promoted=wr>=0.55; let d=0;
    if(promoted){const p=Math.min(Math.max(wr,.05),.95); d=400*Math.log10(p/(1-p)); elo+=d; ver++; promos++; streak=0; last=28+i;}
    else streak++;
    return {iteration:28+i, gate_win_rate:wr, promoted, champion_version:ver, gate_elo:+elo.toFixed(1), elo_delta:+d.toFixed(1)};
  });
  updateGateChart(pts, 0.55);
  out.syntheticBars = gateChart.data.datasets[0].data.length;
  out.syntheticLadder = gateChart.data.datasets[1].data;
  out.barColors = gateChart.data.datasets[0].backgroundColor.map(c=>c.includes('76, 175')?'green':'red');
  out.threshold = gateChart.$gateThreshold;
  out.ladderMonotonic = out.syntheticLadder.every((v,i,a)=>i===0||a[i-1]<=v);
