(() => {
  const cv = gateChart.canvas;
  const ctx = cv.getContext('2d');
  const {width:w, height:h} = cv;
  const img = ctx.getImageData(0, 0, w, h).data;
  const seen = new Map();
  let nonTransparent = 0;
  for (let i = 0; i < img.length; i += 4) {
    const a = img[i+3];
    if (a === 0) continue;
    nonTransparent++;
    const key = `${img[i]},${img[i+1]},${img[i+2]}`;
    seen.set(key, (seen.get(key)||0)+1);
  }
  const top = [...seen.entries()].sort((a,b)=>b[1]-a[1]).slice(0,6);
  // Look for the signature colours we set
  const has = (r,g,b,tol=26) => [...seen.keys()].some(k=>{
    const [R,G,B]=k.split(',').map(Number);
    return Math.abs(R-r)<tol && Math.abs(G-g)<tol && Math.abs(B-b)<tol;
  });
  return JSON.stringify({
    canvasPx: [w,h],
    paintedPixels: nonTransparent,
    distinctColors: seen.size,
    topColors: top,
    hasGreenBars: has(76,175,80),
    hasRedBars: has(239,83,80),
    hasGoldLadder: has(200,149,108),
  }, null, 1);
})();

